#include <cmath>
#include <cstdio>
#include <string>

double frameBudgetMs(int fps)
{
    return fps > 0 ? 1000.0 / fps : 0.0;
}

int framesFor(double seconds, int fps)
{
    return static_cast<int>(std::lround(seconds * fps));
}

std::string fpsLabel(double frameTimeSeconds)
{
    if (frameTimeSeconds <= 0) return "-- FPS";
    char buffer[64];
    std::snprintf(buffer, sizeof(buffer), "%ld FPS (%.1f ms)", std::lround(1.0 / frameTimeSeconds), frameTimeSeconds * 1000.0);
    return buffer;
}

unitTests:
TEST("budgets") { CHECK_NEAR(frameBudgetMs(60), 16.6667, 1e-3); CHECK_NEAR(frameBudgetMs(144), 6.9444, 1e-3); CHECK_NEAR(frameBudgetMs(0), 0.0, 1e-9); }
TEST("frames for a time") { CHECK_EQ(framesFor(2.0, 60), 120); CHECK_EQ(framesFor(0.25, 30), 8); CHECK_EQ(framesFor(0, 60), 0); }
TEST("labels") { CHECK_EQ(fpsLabel(1.0 / 60), std::string("60 FPS (16.7 ms)")); CHECK_EQ(fpsLabel(0.05), std::string("20 FPS (50.0 ms)")); CHECK_EQ(fpsLabel(0), std::string("-- FPS")); }

